CREATE SCHEMA IF NOT EXISTS `cloudsense_dw`
OPTIONS(
  description="CloudSense AI Enterprise FinOps & GreenOps Data Warehouse",
  location="US"
);


-- ----------------------------------------------------------------------------
-- DIMENSION TABLES
-- ----------------------------------------------------------------------------


CREATE OR REPLACE TABLE `cloudsense_dw.dim_date` (
  date_key INT64,
  full_date STRING,
  year INT64,
  quarter INT64,
  month INT64,
  month_name STRING,
  week_of_year INT64,
  day_of_month INT64,
  day_of_week INT64,
  day_name STRING,
  is_weekend BOOL,
  is_month_end BOOL
)
OPTIONS(description="CloudSense AI — dim_date");

CREATE OR REPLACE TABLE `cloudsense_dw.dim_provider` (
  provider_id STRING,
  provider_name STRING,
  cloud_category STRING,
  headquarters STRING
)
OPTIONS(description="CloudSense AI — dim_provider");

CREATE OR REPLACE TABLE `cloudsense_dw.dim_region` (
  region_id STRING,
  region_name STRING,
  country STRING,
  continent STRING,
  pue_factor FLOAT64,
  grid_carbon_intensity_gco2_per_kwh FLOAT64,
  renewable_tier STRING
)
OPTIONS(description="CloudSense AI — dim_region");

CREATE OR REPLACE TABLE `cloudsense_dw.dim_service` (
  service_id STRING,
  service_name STRING,
  service_family STRING,
  pricing_unit STRING,
  pricing_model STRING
)
OPTIONS(description="CloudSense AI — dim_service");

CREATE OR REPLACE TABLE `cloudsense_dw.dim_resource` (
  resource_id STRING,
  resource_name STRING,
  resource_type STRING,
  project_id STRING,
  project_name STRING,
  department STRING,
  cost_center STRING,
  environment STRING,
  service_id STRING,
  region_id STRING,
  pricing_tier STRING,
  provisioned_vcpu FLOAT64,
  provisioned_memory_gb FLOAT64,
  provisioned_storage_gb FLOAT64
)
OPTIONS(description="CloudSense AI — dim_resource");


-- ----------------------------------------------------------------------------
-- FACT TABLES (Partitioned & Clustered)
-- ----------------------------------------------------------------------------


CREATE OR REPLACE TABLE `cloudsense_dw.fact_usage` (
  usage_fact_id STRING,
  date_key INT64,
  usage_date DATE,
  resource_id STRING,
  service_id STRING,
  region_id STRING,
  provider_id STRING,
  runtime_hours FLOAT64,
  usage_quantity FLOAT64,
  pricing_unit STRING,
  avg_cpu_utilization_pct FLOAT64,
  max_cpu_utilization_pct FLOAT64,
  avg_memory_utilization_pct FLOAT64,
  max_memory_utilization_pct FLOAT64,
  disk_read_iops FLOAT64,
  disk_write_iops FLOAT64,
  network_ingress_gb FLOAT64,
  network_egress_gb FLOAT64,
  total_requests INT64,
  is_idle BOOL
)
PARTITION BY usage_date
CLUSTER BY resource_id, service_id, region_id
OPTIONS(description="CloudSense AI — fact_usage");

CREATE OR REPLACE TABLE `cloudsense_dw.fact_cost` (
  cost_fact_id STRING,
  date_key INT64,
  usage_date DATE,
  resource_id STRING,
  service_id STRING,
  region_id STRING,
  provider_id STRING,
  pricing_tier STRING,
  usage_quantity FLOAT64,
  list_unit_price_usd FLOAT64,
  list_cost_usd FLOAT64,
  discount_amount_usd FLOAT64,
  net_cost_usd FLOAT64,
  effective_hourly_rate FLOAT64
)
PARTITION BY usage_date
CLUSTER BY resource_id, service_id, region_id
OPTIONS(description="CloudSense AI — fact_cost");

CREATE OR REPLACE TABLE `cloudsense_dw.fact_carbon` (
  carbon_fact_id STRING,
  date_key INT64,
  usage_date DATE,
  resource_id STRING,
  service_id STRING,
  region_id STRING,
  provider_id STRING,
  runtime_hours FLOAT64,
  server_power_avg_watts FLOAT64,
  energy_consumed_kwh FLOAT64,
  scope2_location_based_gco2e FLOAT64,
  scope3_embodied_gco2e FLOAT64,
  total_carbon_gco2e FLOAT64,
  emissions_per_dollar_usd FLOAT64
)
PARTITION BY usage_date
CLUSTER BY region_id, service_id
OPTIONS(description="CloudSense AI — fact_carbon");

CREATE OR REPLACE TABLE `cloudsense_dw.fact_anomaly` (
  anomaly_fact_id STRING,
  date_key INT64,
  usage_date DATE,
  resource_id STRING,
  service_id STRING,
  region_id STRING,
  provider_id STRING,
  anomaly_type STRING,
  actual_cost_usd FLOAT64,
  expected_cost_usd FLOAT64,
  deviation_usd FLOAT64,
  deviation_pct FLOAT64,
  severity STRING,
  root_cause_description STRING
)
PARTITION BY usage_date
CLUSTER BY severity, anomaly_type, service_id
OPTIONS(description="CloudSense AI — fact_anomaly");


