PARTITION BY usage_date
OPTIONS(description="CloudSense AI — mart_cost_trends");

CREATE OR REPLACE TABLE `cloudsense_dw.mart_resource_utilization` (
  resource_id STRING,
  resource_name STRING,
  service_name STRING,
  resource_type STRING,
  department STRING,
