  total_carbon_kg FLOAT64,
  idle_days_count INT64,
  utilization_tier STRING
)
CLUSTER BY department, environment
OPTIONS(description="CloudSense AI — mart_resource_utilization");

CREATE OR REPLACE TABLE `cloudsense_dw.mart_anomalies` (
  anomaly_type STRING,
  severity STRING,
  root_cause_description STRING,
